package com.atlasiq.api;
import com.atlasiq.security.*;import jakarta.ws.rs.*;import jakarta.ws.rs.core.MediaType;
@Path("/api/security") @Produces(MediaType.APPLICATION_JSON)
public class SupplyChainSecurityResource {private final SbomService sbom;private final SecurityPostureService posture;private final SecurityBlastRadiusService blast;public SupplyChainSecurityResource(SbomService s,SecurityPostureService p,SecurityBlastRadiusService b){sbom=s;posture=p;blast=b;}@GET @Path("/{id}/sbom/cyclonedx") public Object cdx(@PathParam("id")String id){return sbom.cyclonedx(id);}@GET @Path("/{id}/sbom/spdx") public Object spdx(@PathParam("id")String id){return sbom.spdx(id);}@GET @Path("/{id}/posture") public Object posture(@PathParam("id")String id){return posture.analyze(id);}@GET @Path("/{id}/blast-radius/{resource}") public Object blast(@PathParam("id")String id,@PathParam("resource")String resource,@QueryParam("depth")@DefaultValue("3")int depth){return blast.analyze(id,resource,depth);}}
